#!/usr/bin/env node
/**
 * Cross-database integration matrix for Issue #37.
 *
 * Spins up throwaway PostgreSQL / MySQL / MariaDB containers, runs the exact
 * DetailHandler query patterns (generated by Knex) against each real engine via
 * `docker exec`, and asserts the results. SQLite is exercised in-process through
 * the built-in node:sqlite module (no container, no driver).
 *
 * This needs no DB driver installed (mysql2/pg/sqlite3) - Knex only generates the
 * SQL; execution happens in the real engines. The CI-friendly, container-less
 * subset of these checks also lives in test/db-compatibility.test.ts.
 *
 * Usage:
 *   node test/integration/db-matrix.cjs            # manage containers + run + cleanup
 *   node test/integration/db-matrix.cjs --keep     # leave containers running
 *
 * Requires: Docker, and the postgres:15 / mysql:8 / mariadb:11 images
 * (pulled automatically if missing and a registry is reachable).
 */
const { execSync } = require('child_process');
const path = require('path');

const knex = require(path.resolve(__dirname, '../../node_modules/knex'));

const KEEP = process.argv.includes('--keep');
const COLLECTION = 'blocks_text';
const NUMERIC_IDS = [1, 2, 3];
const STRING_IDS = NUMERIC_IDS.map(String);

// --- DetailHandler query patterns (mirrored from src/handlers/DetailHandler.ts) ----
function itemsSql(client) {
    return knexClient(client)
        .select(['id', 'title', 'status'])
        .from(COLLECTION)
        .whereIn('id', NUMERIC_IDS)
        .toString();
}
function pageUsageSql(client) {
    return knexClient(client)
        .select(['m2a.id', 'm2a.item', 'm2a.sort', 'p.title as page_title', 'p.status as page_status'])
        .from('pages_m2a as m2a')
        .leftJoin('pages as p', 'm2a.pages_id', 'p.id')
        .where('m2a.collection', COLLECTION)
        .whereIn('m2a.item', STRING_IDS)
        .toString();
}
function expandableUsageSql(client) {
    return knexClient(client)
        .select(['ee.id', 'ee.item', 'ee.area', 'e.status as parent_status'])
        .from('expandable_expandable as ee')
        .leftJoin('expandable as e', 'ee.expandable_id', 'e.id')
        .where('ee.collection', COLLECTION)
        .whereIn('ee.item', STRING_IDS)
        .toString();
}
function knexClient(client) {
    return knex({ client, useNullAsDefault: true });
}

const SCHEMA = `
DROP TABLE IF EXISTS pages_m2a;
DROP TABLE IF EXISTS expandable_expandable;
DROP TABLE IF EXISTS blocks_text;
DROP TABLE IF EXISTS pages;
DROP TABLE IF EXISTS expandable;
CREATE TABLE blocks_text (id INT PRIMARY KEY, title VARCHAR(255), status VARCHAR(50));
CREATE TABLE pages (id INT PRIMARY KEY, title VARCHAR(255), status VARCHAR(50), slug VARCHAR(255));
CREATE TABLE pages_m2a (id INT PRIMARY KEY, pages_id INT, collection VARCHAR(255), item VARCHAR(255), sort INT);
CREATE TABLE expandable (id INT PRIMARY KEY, status VARCHAR(50), area VARCHAR(50));
CREATE TABLE expandable_expandable (id INT PRIMARY KEY, expandable_id INT, collection VARCHAR(255), item VARCHAR(255), sort INT, area VARCHAR(50));
INSERT INTO blocks_text VALUES (1,'Hero','published'),(2,'Intro','draft'),(3,'Footer','published');
INSERT INTO pages VALUES (10,'Landing','published','landing');
INSERT INTO pages_m2a VALUES (101,10,'blocks_text','1',1),(102,10,'blocks_text','3',2);
INSERT INTO expandable VALUES (20,'draft','main');
INSERT INTO expandable_expandable VALUES (201,20,'blocks_text','2',1,'main');
`;

const ENGINES = [
    {
        name: 'PostgreSQL',
        client: 'pg',
        container: 'eb-matrix-pg',
        image: 'postgres:15-alpine',
        run: 'docker run -d --name eb-matrix-pg -e POSTGRES_PASSWORD=test -e POSTGRES_DB=ebtest postgres:15-alpine',
        ready: 'docker exec eb-matrix-pg pg_isready -U postgres -d ebtest',
        readyToken: 'accepting',
        exec: (sql) => sh('docker exec -i eb-matrix-pg psql -U postgres -d ebtest -t -A -F"\t" -P pager=off', sql),
    },
    {
        name: 'MySQL',
        client: 'mysql2',
        container: 'eb-matrix-mysql',
        image: 'mysql:8.0',
        run: 'docker run -d --name eb-matrix-mysql -e MYSQL_ROOT_PASSWORD=test -e MYSQL_DATABASE=ebtest mysql:8.0',
        ready: 'docker exec eb-matrix-mysql mysqladmin ping -uroot -ptest --silent',
        readyToken: 'alive',
        exec: (sql) => sh('docker exec -i eb-matrix-mysql mysql -uroot -ptest --batch -N ebtest', sql),
    },
    {
        name: 'MariaDB',
        client: 'mysql2',
        container: 'eb-matrix-mariadb',
        image: 'mariadb:11',
        run: 'docker run -d --name eb-matrix-mariadb -e MARIADB_ROOT_PASSWORD=test -e MARIADB_DATABASE=ebtest mariadb:11',
        ready: 'docker exec eb-matrix-mariadb mariadb-admin ping -uroot -ptest --silent',
        readyToken: 'alive',
        exec: (sql) => sh('docker exec -i eb-matrix-mariadb mariadb -uroot -ptest --batch -N ebtest', sql),
    },
];

function sh(cmd, input) {
    return execSync(cmd, { input: input || '', encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] });
}
function rows(out) {
    return out.split('\n').map((l) => l.trim()).filter(Boolean);
}
function assert(cond, msg) {
    if (!cond) throw new Error(`ASSERT FAILED: ${msg}`);
}

function waitReady(engine) {
    for (let i = 0; i < 60; i++) {
        try {
            const out = execSync(`${engine.ready} 2>&1`, { encoding: 'utf8' });
            if (out.includes(engine.readyToken)) return;
        } catch { /* not ready yet */ }
        execSync('sleep 2');
    }
    throw new Error(`${engine.name} did not become ready in time`);
}

function testEngine(engine) {
    console.log(`\n### ${engine.name} (${engine.client}) ###`);
    if (!KEEP) {
        try { sh(`docker rm -f ${engine.container}`); } catch { /* ignore */ }
        sh(engine.run);
    }
    waitReady(engine);
    engine.exec(SCHEMA);

    const items = rows(engine.exec(itemsSql(engine.client) + ';'));
    assert(items.length === 3, `${engine.name} loadItems should return 3 rows, got ${items.length}`);

    const pageUsage = rows(engine.exec(pageUsageSql(engine.client) + ';'));
    assert(pageUsage.length === 2, `${engine.name} pageUsage should return 2 rows, got ${pageUsage.length}`);

    const expandableUsage = rows(engine.exec(expandableUsageSql(engine.client) + ';'));
    assert(expandableUsage.length === 1, `${engine.name} expandableUsage should return 1 row, got ${expandableUsage.length}`);

    console.log(`  ✅ items=${items.length} pageUsage=${pageUsage.length} expandableUsage=${expandableUsage.length}`);
}

function testSqlite() {
    console.log(`\n### SQLite (node:sqlite) ###`);
    let DatabaseSync;
    try { ({ DatabaseSync } = require('node:sqlite')); }
    catch { console.log('  ↓ skipped (node:sqlite unavailable - needs Node >= 22)'); return; }

    const db = new DatabaseSync(':memory:');
    db.exec(SCHEMA.replace(/INT PRIMARY KEY/g, 'INTEGER PRIMARY KEY'));
    const exec = (qb) => { const c = qb.toSQL(); return db.prepare(c.sql).all(...c.bindings); };

    const items = exec(knexClient('sqlite3').select(['id', 'title', 'status']).from(COLLECTION).whereIn('id', NUMERIC_IDS));
    assert(items.length === 3, `SQLite loadItems should return 3 rows, got ${items.length}`);
    const pageUsage = exec(knexClient('sqlite3')
        .select(['m2a.id', 'm2a.item']).from('pages_m2a as m2a')
        .leftJoin('pages as p', 'm2a.pages_id', 'p.id')
        .where('m2a.collection', COLLECTION).whereIn('m2a.item', STRING_IDS));
    assert(pageUsage.length === 2, `SQLite pageUsage should return 2 rows, got ${pageUsage.length}`);
    const expandableUsage = exec(knexClient('sqlite3')
        .select(['ee.id', 'ee.item']).from('expandable_expandable as ee')
        .leftJoin('expandable as e', 'ee.expandable_id', 'e.id')
        .where('ee.collection', COLLECTION).whereIn('ee.item', STRING_IDS));
    assert(expandableUsage.length === 1, `SQLite expandableUsage should return 1 row, got ${expandableUsage.length}`);
    db.close();
    console.log(`  ✅ items=${items.length} pageUsage=${pageUsage.length} expandableUsage=${expandableUsage.length}`);
}

function cleanup() {
    if (KEEP) { console.log('\n(--keep) containers left running.'); return; }
    for (const e of ENGINES) { try { sh(`docker rm -f ${e.container}`); } catch { /* ignore */ } }
    console.log('\nContainers removed.');
}

(function main() {
    console.log('Issue #37 - cross-database integration matrix');
    let failed = false;
    try {
        for (const engine of ENGINES) {
            try { testEngine(engine); }
            catch (err) { failed = true; console.error(`  ❌ ${engine.name}: ${err.message}`); }
        }
        try { testSqlite(); }
        catch (err) { failed = true; console.error(`  ❌ SQLite: ${err.message}`); }
    } finally {
        cleanup();
    }
    console.log(failed ? '\n❌ MATRIX FAILED' : '\n✅ MATRIX PASSED (all engines)');
    process.exit(failed ? 1 : 0);
})();
